Local Ltac acc_hint ::=
  lazymatch goal with
  | |- acc_in ?R (Z_to_bv 64 (Z.shiftr ?a 3 + 2147450880), 1%nat) =>
      match goal with H : rng R (shad ?A) (nshad (?len + ?A' mod 8)) |- _ => constr_eq A A'; apply (acc_shZ R A len a H); lia end
  end.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section CANSEC1. Context {rc : runConstT}.

Section FW1A.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (m0 : amem) (DT WK T nbb maxW minB scl : Z) (sorted : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis PLC : x2placeA RNG m0 SPA DT WK js ncells.
  Notation INV m1 dt := (x2fA_inv m0 m1 SPA DT WK T nbb maxW minB scl js jt sorted ncells dt).
  Notation CW6 := [(DT + 4, DT + 4 + 4 * Z.of_nat ncells); (SPA + 624, SPA + 704)].

  Lemma fw1A : forall dt m1 r b e nb start jsp
      (x1 x5 x6 x7 x11 x12 x13 x14 x15 x17 x18 x19 x20 x21 x22 x23 x26 x27 x28 x29 x30 x31 : word),
    fill_for_weight (S (Z.to_nat (e - b))) dt start b e nb T 0 1 sorted = Ok r ->
    1 <= nb <= T -> T <= 12 -> 0 <= b <= e -> e <= 256 -> 0 <= start < 2^30 ->
    INV m1 dt -> rw_cells asegs m1 (SPA + 288) [C8 (Z_to_bv 64 e)] -> rw_cells asegs m1 (SPA + 624) [CB 80 jsp] ->
    (forall m2 dt' jsp' (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23 y25 y26 y27 y28 y29 y30 y31 : word),
       fst r = dt' -> INV m2 dt' -> rw_cells asegs m2 (SPA + 288) [C8 (Z_to_bv 64 e)] ->
       rw_cells asegs m2 (SPA + 624) [CB 80 jsp'] -> munch CW6 m1 m2 -> wmono asegs m1 m2 ->
       evtF asegs RNG Q (x2nextA SP SPA gp tp F fc m2 y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23
                           y25 y26 y27 y28 y29 y30 y31)) ->
    evtF asegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) (Z_to_bv 64 nb) x11
               (Z_to_bv 64 (T - nb)) x13 x14 x15 (Z_to_bv 64 b) x17 x18 x19 x20 x21 x22 x23 (Z_to_bv 64 2147450880)
               (Z_to_bv 64 start) x26 x27 x28 x29 x30 x31)
